if ( preg_match( '#/uploads/learn/([a-z0-9-]+)\.webp"#', $img, $m ) && false !== strpos( $img, 'fetchpriority="high"' ) ) {
	if ( $m[1] !== get_post_field( 'post_name', get_queried_object_id() ) ) {
		// Hub "featured story": not this page's LCP (D09).
		$img = str_replace( array( ' fetchpriority="high"', ' loading="eager"' ), array( '', ' loading="lazy"' ), $img );
		return preg_replace( '#,\s*[^,"\s]+/uploads/learn/[a-z0-9-]+\.webp\s+\d+w#', '', $img );
	}
